use common::commas;
use common::source::Source;
use regex::{Captures, Regex};
use std::sync::OnceLock;

/// The Grand Exchange takes 2% of a sale, rounded down, capped per item.
/// 1% until 29 May 2025. https://oldschool.runescape.wiki/w/Grand_Exchange
const GE_TAX_PERCENT: u64 = 2;
const GE_TAX_CAP: u64 = 5_000_000;

/// Items the Grand Exchange sells without the convenience fee.
/// https://oldschool.runescape.wiki/w/Grand_Exchange#Exempt_from_tax
/// Generated by `scripts/gen-tax-exempt.js`; re-run it to refresh.
pub const TAX_EXEMPT_IDS: &[u32] = &[
    233,   // Pestle and mortar
    315,   // Shrimps
    329,   // Salmon
    347,   // Herring
    351,   // Pike
    355,   // Mackerel
    361,   // Tuna
    365,   // Bass
    379,   // Lobster
    558,   // Mind rune
    806,   // Bronze dart
    807,   // Iron dart
    808,   // Steel dart
    882,   // Bronze arrow
    884,   // Iron arrow
    886,   // Steel arrow
    952,   // Spade
    1733,  // Needle
    1735,  // Shears
    1755,  // Chisel
    1785,  // Glassblowing pipe
    1891,  // Cake
    2140,  // Cooked chicken
    2142,  // Cooked meat
    2309,  // Bread
    2327,  // Meat pie
    2347,  // Hammer
    2552,  // Ring of dueling(8)
    3008,  // Energy potion(4)
    3010,  // Energy potion(3)
    3012,  // Energy potion(2)
    3014,  // Energy potion(1)
    3853,  // Games necklace(8)
    5325,  // Gardening trowel
    5329,  // Secateurs
    5331,  // Watering can
    5341,  // Rake
    5343,  // Seed dibber
    8007,  // Varrock teleport (tablet)
    8008,  // Lumbridge teleport (tablet)
    8009,  // Falador teleport (tablet)
    8010,  // Camelot teleport (tablet)
    8011,  // Ardougne teleport (tablet)
    8013,  // Teleport to house (tablet)
    8794,  // Saw
    13190, // Old school bond
    28790, // Kourend castle teleport (tablet)
    28824, // Civitas illa fortis teleport
];

/// The tax on selling one item. Integer maths throughout: 2% of 991 is 19, not
/// 19.82, and a float would round the wrong way on exact multiples.
pub fn tax(price: u64) -> u64 {
    (price * GE_TAX_PERCENT / 100).min(GE_TAX_CAP)
}

/// The tax on selling one of item `id`, or `None` when it is exempt.
pub fn tax_on(id: u32, price: u64) -> Option<u64> {
    (!TAX_EXEMPT_IDS.contains(&id)).then(|| tax(price))
}

/// The tax on selling `count` of item `id` at `price` each - the cap applies
/// per item, so this is one item's tax times the count - and how to show it.
pub fn tax_note(s: &Source, id: u32, price: u64, count: u64) -> (String, u64) {
    match tax_on(id, price) {
        Some(each) => {
            let total = each * count.max(1);
            (s.p(&format!("-{} tax", commas(total as f64, "d"))), total)
        }
        None => (s.p("tax exempt"), 0),
    }
}

/// The Total line under a multi-item lookup, with the summed tax when `-t`
/// was asked for.
pub fn total_line(s: &Source, value: f64, tax: Option<u64>) -> String {
    let line = format!(
        "{} {}{}",
        s.l("Total"),
        s.c2(&commas(value, "d")),
        s.c1("gp")
    );

    match tax {
        Some(tax) => format!(
            "{} {}",
            line,
            s.p(&format!("-{} tax", commas(tax as f64, "d")))
        ),
        None => line,
    }
}

fn tax_flag_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"(^|[\s,])-t([\s,]|$)").unwrap())
}

/// Splits a `-t` flag off an item query: the query without it, and whether
/// it was there.
pub fn strip_tax_flag(query: &str) -> (String, bool) {
    let re = tax_flag_regex();
    let found = re.is_match(query);

    // Keep the separators either side, so "a -t, b" stays two items, but not
    // both spaces of "a -t b", which would leave a double space in the search.
    let stripped = re.replace_all(query, |c: &Captures| match (&c[1], &c[2]) {
        (before, " ") if before.trim().is_empty() => before.to_string(),
        (before, after) => format!("{}{}", before, after),
    });

    (stripped.trim().to_string(), found)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tax_is_two_percent_rounded_down() {
        assert_eq!(tax(991), 19);
        assert_eq!(tax(100), 2);
        assert_eq!(tax(50), 1);
    }

    #[test]
    fn tax_below_fifty_gp_rounds_away_to_nothing() {
        assert_eq!(tax(49), 0);
        assert_eq!(tax(1), 0);
        assert_eq!(tax(0), 0);
    }

    #[test]
    fn tax_is_capped_at_five_million() {
        assert_eq!(tax(250_000_000), 5_000_000);
        assert_eq!(tax(1_000_000_000), 5_000_000);
    }

    #[test]
    fn exempt_items_pay_no_tax() {
        // Old school bond, Games necklace(8)
        assert_eq!(tax_on(13190, 10_000_000), None);
        assert_eq!(tax_on(3853, 1_000), None);
        // Shark
        assert_eq!(tax_on(385, 991), Some(19));
    }

    #[test]
    fn only_the_charged_games_necklace_is_exempt() {
        // Games necklace(7)
        assert_eq!(tax_on(3855, 1_000), Some(20));
    }

    #[test]
    fn tax_flag_is_stripped_from_the_query() {
        assert_eq!(strip_tax_flag("-t shark"), ("shark".to_string(), true));
        assert_eq!(strip_tax_flag("shark -t"), ("shark".to_string(), true));
        assert_eq!(
            strip_tax_flag("5 shark -t, lobster"),
            ("5 shark , lobster".to_string(), true)
        );
        assert_eq!(
            strip_tax_flag("shark -t lobster"),
            ("shark lobster".to_string(), true)
        );
        assert_eq!(strip_tax_flag("shark"), ("shark".to_string(), false));
        // Only a whole word: item names with "-t" inside are left alone.
        assert_eq!(
            strip_tax_flag("x-t shark"),
            ("x-t shark".to_string(), false)
        );
    }
}
